38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
42	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
43	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.advice.OwnerCityCapacityExceededException;
