53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
72	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization. Keys and values are
78	     * upper-cased, matching the state of the address after whitespace and case normalization.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
81	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredOwnerFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
133	        owner.setTelephone(normalizedTelephone);
134	        owner.setEmail(normalizeEmail(owner.getEmail()));
135	        owner.setAddress(normalizeAddress(owner.getAddress()));
136	        LocalDate effectiveRegistrationDate =
137	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
138	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
139	        rejectDuplicateTelephone(normalizedTelephone);
140	        rejectDailyLimitReached(owner.getRegistrationDate());
141	        rejectCityAtCapacity(owner.getCity());
142	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
143	            assignHousehold(owner);
144	        } else {
145	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
146	        }
147	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
148	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        this.clinicService.deleteOwner(owner);
182	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        HttpHeaders headers = new HttpHeaders();
193	        Pet pet = petMapper.toPet(petFieldsDto);
194	        owner.setId(ownerId);
195	        pet.setOwner(owner);
196	        pet.getType().setName(null);
197	        this.clinicService.savePet(pet);
198	        PetDto petDto = petMapper.toPetDto(pet);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
200	            .buildAndExpand(pet.getId()).toUri());
201	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner != null) {
209	            Pet currentPet = this.clinicService.findPetById(petId);
210	            if (currentPet != null) {
211	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
212	                currentPet.setName(petFieldsDto.getName());
213	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
214	                this.clinicService.savePet(currentPet);
215	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
232	            .buildAndExpand(visit.getId()).toUri());
233	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
234	    }
235	
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
252	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
253	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
254	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
255	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
256	     * Springfield gets {@code 'SPR-SMI-0011'}.
257	     *
258	     * @param city the owner's city
259	     * @param lastName the owner's last name
260	     * @return the assigned customer code
261	     */
262	    /**
263	     * Counts how many existing owners share the given first and last name, compared
264	     * case-insensitively, at the moment before the new owner is persisted. The result is
265	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
266	     * stood when the owner was created rather than being recomputed on later reads.
267	     *
268	     * @param firstName the first name of the owner being created
269	     * @param lastName the last name of the owner being created
270	     * @return the number of pre-existing owners with the same first and last name
271	     */
272	    private int countNamesakes(String firstName, String lastName) {
273	        String first = firstName == null ? "" : firstName;
274	        String last = lastName == null ? "" : lastName;
275	        return (int) this.clinicService.findAllOwners().stream()
276	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
277	                && last.equalsIgnoreCase(existing.getLastName()))
278	            .count();
279	    }
280	
281	    private String nextCustomerCode(String city, String lastName) {
282	        String cityLetters = city == null ? "" : city;
283	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
284	        String letters = lastName == null ? "" : lastName;
285	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
286	        String normalizedCity = normalizeForComparison(city);
287	        int sequence = (int) this.clinicService.findAllOwners().stream()
288	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
289	            .count() + 1;
290	        return String.format("%s-%s-%04d", city3, last3, sequence);
291	    }
292	
293	    /**
294	     * Rejects an owner payload that is missing or blank in any of the required fields
295	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
296	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
297	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
298	     * guard enforces the rule uniformly for every required field.
299	     *
300	     * @param ownerFieldsDto the submitted owner payload
301	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
302	     */
303	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
304	        List<String> invalidFields = new ArrayList<>();
305	        if (isBlank(ownerFieldsDto.getFirstName())) {
306	            invalidFields.add("firstName");
307	        }
308	        if (isBlank(ownerFieldsDto.getLastName())) {
309	            invalidFields.add("lastName");
310	        }
311	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
312	            invalidFields.add("address");
313	        }
314	        if (isBlank(ownerFieldsDto.getCity())) {
315	            invalidFields.add("city");
316	        }
317	        if (isBlank(ownerFieldsDto.getTelephone())) {
318	            invalidFields.add("telephone");
319	        }
320	        if (!invalidFields.isEmpty()) {
321	            throw new InvalidOwnerFieldsException(invalidFields);
322	        }
323	    }
324	
325	    private boolean isBlank(String value) {
326	        return value == null || value.isBlank();
327	    }
328	
329	    /**
330	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
331	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
332	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
333	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
334	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
335	     *
336	     * @param telephone the raw telephone value from the submitted owner payload
337	     * @return the normalized E.164 telephone number
338	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
339	     */
340	    private String normalizeTelephone(String telephone) {
341	        String raw = telephone == null ? "" : telephone.strip();
342	        boolean hasCountryCode = raw.startsWith("+");
343	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
344	        String digits;
345	        if (hasCountryCode) {
346	            digits = cleaned.substring(1);
347	        } else {
348	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
349	            digits = "61" + national;
350	        }
351	        if (!digits.matches("[0-9]{8,15}")) {
352	            throw new InvalidOwnerFieldsException(List.of("telephone"));
353	        }
354	        return "+" + digits;
355	    }
356	
357	    /**
358	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
359	     * returning {@code null} when the value cannot form a valid E.164 number.
360	     *
361	     * @param telephone an existing owner's stored telephone value
362	     * @return the E.164 form, or {@code null} if it cannot be normalized
363	     */
364	    private String toE164OrNull(String telephone) {
365	        try {
366	            return normalizeTelephone(telephone);
367	        } catch (InvalidOwnerFieldsException ex) {
368	            return null;
369	        }
370	    }
371	
372	    /**
373	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
374	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
375	     * accepted value is trimmed and lower-cased before it is stored and returned.
376	     *
377	     * @param email the raw email value from the submitted owner payload, may be {@code null}
378	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
379	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
380	     */
381	    private String normalizeEmail(String email) {
382	        if (email == null) {
383	            return null;
384	        }
385	        String trimmed = email.strip();
386	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
387	            throw new InvalidOwnerFieldsException(List.of("email"));
388	        }
389	        return trimmed.toLowerCase(Locale.ROOT);
390	    }
391	
392	    /**
393	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
394	     * Existing owners' telephones are converted to E.164 form before comparison so that
395	     * differently-formatted representations of the same number are treated as duplicates.
396	     *
397	     * @param normalizedTelephone the E.164 telephone of the owner being created
398	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
399	     */
400	    private void rejectDuplicateTelephone(String normalizedTelephone) {
401	        boolean duplicate = this.clinicService.findAllOwners().stream()
402	            .map(Owner::getTelephone)
403	            .filter(telephone -> telephone != null)
404	            .map(this::toE164OrNull)
405	            .filter(telephone -> telephone != null)
406	            .anyMatch(normalizedTelephone::equals);
407	        if (duplicate) {
408	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
409	        }
410	    }
411	
412	    /**
413	     * The maximum number of owners a single city may contain. Once a city already holds this many
414	     * owners, creating another owner in that city is rejected.
415	     */
416	    private static final int MAX_OWNERS_PER_CITY = 50;
417	
418	    /**
419	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
420	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
421	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
422	     * counting used elsewhere.
423	     *
424	     * @param city the city of the owner being created
425	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
426	     */
427	    /**
428	     * The maximum number of owners that may be registered on a single day. Once this many owners
429	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
430	     */
431	    private static final int MAX_OWNERS_PER_DAY = 100;
432	
433	    /**
434	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
435	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
436	     * registration date of the owner being created.
437	     *
438	     * @param registrationDate the registration date of the owner being created
439	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
440	     */
441	    /**
442	     * Rolls an effective registration date forward onto a business day. A registration date must fall
443	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
444	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
445	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
446	     * count, the membership number's year segment, and so on) uses this adjusted date.
447	     *
448	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
449	     * @return the same date if it is a weekday, otherwise the following Monday
450	     */
451	    private LocalDate rollToBusinessDay(LocalDate date) {
452	        DayOfWeek day = date.getDayOfWeek();
453	        if (day == DayOfWeek.SATURDAY) {
454	            return date.plusDays(2);
455	        }
456	        if (day == DayOfWeek.SUNDAY) {
457	            return date.plusDays(1);
458	        }
459	        return date;
460	    }
461	
462	    private void rejectDailyLimitReached(LocalDate registrationDate) {
463	        long ownersToday = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
465	            .count();
466	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
467	            throw new DailyOwnerLimitExceededException(registrationDate);
468	        }
469	    }
470	
471	    private void rejectCityAtCapacity(String city) {
472	        String normalizedCity = normalizeForComparison(city);
473	        long ownersInCity = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
475	            .count();
476	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
477	            throw new OwnerCityCapacityExceededException(city);
478	        }
479	    }
480	
481	    /**
482	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
483	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
484	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
485	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
486	     *
487	     * @param lastName the last name of the owner being created
488	     * @param address the address of the owner being created
489	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
490	     */
491	    private void rejectDuplicateHousehold(String lastName, String address) {
492	        String normalizedLastName = normalizeForComparison(lastName);
493	        String normalizedAddress = normalizeAddress(address);
494	        boolean duplicate = this.clinicService.findAllOwners().stream()
495	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
496	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
497	        if (duplicate) {
498	            throw new DuplicateOwnerHouseholdException(lastName, address);
499	        }
500	    }
501	
502	    /**
503	     * Assigns the owner being created a household identifier when the request opts into sharing a
504	     * household. The identifier is a stable value derived from the owner's normalized last name and
505	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
506	     * value regardless of creation order. Any already-existing owner in the same household that has no
507	     * identifier yet is back-filled with the same value so the whole household stays consistent.
508	     *
509	     * @param owner the owner being created, whose household id is set in place
510	     */
511	    private void assignHousehold(Owner owner) {
512	        String householdId = householdId(owner.getLastName(), owner.getAddress());
513	        String normalizedLastName = normalizeForComparison(owner.getLastName());
514	        String normalizedAddress = normalizeAddress(owner.getAddress());
515	        for (Owner existing : this.clinicService.findAllOwners()) {
516	            if (existing.getHouseholdId() == null
517	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
518	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
519	                existing.setHouseholdId(householdId);
520	                this.clinicService.saveOwner(existing);
521	            }
522	        }
523	        owner.setHouseholdId(householdId);
524	    }
525	
526	    /**
527	     * Derives the stable household identifier for a given last name and address. The value is
528	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
529	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
530	     * the same household therefore always produce the same identifier.
531	     *
532	     * @param lastName the owner's last name
533	     * @param address the owner's address
534	     * @return the stable household identifier
535	     */
536	    private String householdId(String lastName, String address) {
537	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
538	        try {
539	            byte[] digest = MessageDigest.getInstance("SHA-256")
540	                .digest(key.getBytes(StandardCharsets.UTF_8));
541	            StringBuilder hex = new StringBuilder();
542	            for (int i = 0; i < 6; i++) {
543	                hex.append(String.format("%02X", digest[i]));
544	            }
545	            return "HH-" + hex;
546	        } catch (NoSuchAlgorithmException ex) {
547	            throw new IllegalStateException("SHA-256 not available", ex);
548	        }
549	    }
550	
551	    /**
552	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
553	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
554	     * result is lower-cased. A {@code null} value normalizes to the empty string.
555	     *
556	     * @param value the value to normalize, may be {@code null}
557	     * @return the normalized value
558	     */
559	    private String normalizeForComparison(String value) {
560	        if (value == null) {
561	            return "";
562	        }
563	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
564	    }
565	
566	    /**
567	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
568	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
569	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
570	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
571	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
572	     * that is stored, returned, and used for every address comparison (household duplicate detection
573	     * and the shared household id).
574	     *
575	     * @param address the raw address value from the submitted owner payload, may be {@code null}
576	     * @return the normalized address
577	     */
578	    private String normalizeAddress(String address) {
579	        if (address == null) {
580	            return "";
581	        }
582	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
583	        if (collapsed.isEmpty()) {
584	            return "";
585	        }
586	        String[] tokens = collapsed.split(" ");
587	        StringBuilder normalized = new StringBuilder();
588	        for (int i = 0; i < tokens.length; i++) {
589	            if (i > 0) {
590	                normalized.append(' ');
591	            }
592	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
593	        }
594	        return normalized.toString();
595	    }
596	}
